input.command:
node -e "
const fs = require('node:fs');
const path = require('node:path');
const url = require('node:url');
(async () => {
  const {coastPostprocess} = await import(url.pathToFileURL('docs/prototypes/new-game/T64/layout.mjs').href);
  const input = JSON.parse(fs.readFileSync('docs/prototypes/new-game/T63/board.json'));
  const result = coastPostprocess(input);
  const jsonStr = JSON.stringify(result, null, 2) + '\n';
  const acc = JSON.parse(fs.readFileSync('docs/prototypes/new-game/T64/acceptance/board.json'));
  const accStr = JSON.stringify(acc, null, 2) + '\n';
  console.log('match:', jsonStr === accStr);
  if (jsonStr !== accStr) {
    console.log('first diff at byte', [...Array(Math.min(jsonStr.length, accStr.length)).keys()].find(i => jsonStr[i] !== accStr[i]));
  }
})();
"

